import {
  FIELD,
  FIELD_SCALE,
  MAX_TWIRLS,
  PAINT,
  PIXEL_BUDGET,
  SCREEN,
  STIR_RADIUS,
  VERTEX,
} from './balatro-shaders';
import type {
  BalatroEngine,
  BalatroPointer,
  BalatroProgram,
  BalatroRgb,
  BalatroSettings,
  BalatroTarget,
  BalatroTwirl,
  BalatroUniforms,
} from './types';

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function parseColor(value: string): BalatroRgb | null {
  const text = String(value || '').trim();
  const hex = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(text);
  if (hex?.[1]) {
    const digits = hex[1];
    const full =
      digits.length === 3
        ? digits.replace(/./g, (digit) => digit + digit)
        : digits;
    return [
      Number.parseInt(full.slice(0, 2), 16) / 255,
      Number.parseInt(full.slice(2, 4), 16) / 255,
      Number.parseInt(full.slice(4, 6), 16) / 255,
    ];
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i.exec(text);
  if (rgb) {
    return [
      clamp(Number.parseFloat(rgb[1] ?? '0') / 255, 0, 1),
      clamp(Number.parseFloat(rgb[2] ?? '0') / 255, 0, 1),
      clamp(Number.parseFloat(rgb[3] ?? '0') / 255, 0, 1),
    ];
  }
  return null;
}

function smoother(t: number): number {
  const x = clamp(t, 0, 1);
  return x * x * x * (x * (x * 6 - 15) + 10);
}

function compile(
  gl: WebGL2RenderingContext,
  type: number,
  source: string,
): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.error(gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

function link(
  gl: WebGL2RenderingContext,
  source: string,
): BalatroProgram | null {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, source);
  const program = vertex && fragment ? gl.createProgram() : null;
  if (!vertex || !fragment || !program) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error(gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: BalatroUniforms = {};
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let index = 0; index < count; index++) {
    const info = gl.getActiveUniform(program, index);
    if (!info) continue;
    const location = gl.getUniformLocation(program, info.name);
    if (location) uniforms[info.name.replace(/\[0\]$/, '')] = location;
  }
  return { program, uniforms };
}

function u(uniforms: BalatroUniforms, name: string) {
  return uniforms[name] ?? null;
}

/**
 * Creates the WebGL2 paint renderer. Returns null when WebGL2 or the shaders
 * are unavailable. `firstRun` enables the intro (it is skipped after a
 * context restore).
 */
export function createBalatroEngine(
  container: HTMLElement,
  canvas: HTMLCanvasElement,
  getSettings: () => BalatroSettings,
  reduced: boolean,
  firstRun: boolean,
  onRestored: () => void,
): BalatroEngine | null {
  const context = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  if (!context) return null;
  const gl: WebGL2RenderingContext = context;
  const paintProgram = link(gl, PAINT);
  const screenProgram = link(gl, SCREEN);
  if (!paintProgram || !screenProgram) {
    if (paintProgram) gl.deleteProgram(paintProgram.program);
    if (screenProgram) gl.deleteProgram(screenProgram.program);
    return null;
  }
  const floatTargets = Boolean(
    gl.getExtension('EXT_color_buffer_float') ||
    gl.getExtension('EXT_color_buffer_half_float'),
  );
  const fieldProgram = floatTargets ? link(gl, FIELD) : null;

  const vao = gl.createVertexArray();
  const view = {
    cssWidth: 1,
    cssHeight: 1,
    block: 1,
    device: 1,
    width: 1,
    height: 1,
    crt: false,
  };
  const paintTarget = {
    texture: gl.createTexture(),
    framebuffer: gl.createFramebuffer(),
    width: 0,
    height: 0,
  };
  let fieldTargets: BalatroTarget[] = [];
  const field = { width: 0, height: 0, energy: 0 };
  const pointer = {
    x: 0,
    y: 0,
    lastX: 0,
    lastY: 0,
    vx: 0,
    inside: false,
    ready: false,
  };
  const steer = { value: 0 };
  const twirls: BalatroTwirl[] = [];
  const twirlData = new Float32Array(MAX_TWIRLS * 4);
  let flow = 14;
  let spin = 0;
  let opening = getSettings().intro && !reduced && firstRun ? 0 : 1;
  let raf = 0;
  let last = 0;
  let visible = true;
  let pageVisible = document.visibilityState !== 'hidden';
  let lost = false;

  const makeTarget = (width: number, height: number): BalatroTarget => {
    const texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RG16F,
      width,
      height,
      0,
      gl.RG,
      gl.HALF_FLOAT,
      null,
    );
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    const framebuffer = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.framebufferTexture2D(
      gl.FRAMEBUFFER,
      gl.COLOR_ATTACHMENT0,
      gl.TEXTURE_2D,
      texture,
      0,
    );
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    return { texture, framebuffer };
  };

  const dropField = () => {
    fieldTargets.forEach((target) => {
      gl.deleteTexture(target.texture);
      gl.deleteFramebuffer(target.framebuffer);
    });
    fieldTargets = [];
    field.width = 0;
    field.height = 0;
    field.energy = 0;
  };

  const resize = () => {
    if (lost) return;
    const s = getSettings();
    const rect = container.getBoundingClientRect();
    const cssWidth = Math.max(1, rect.width);
    const cssHeight = Math.max(1, rect.height);
    const dpr = Math.min(window.devicePixelRatio || 1, s.maxRatio);
    const budget = Math.ceil(
      Math.sqrt((cssWidth * cssHeight * dpr * dpr) / PIXEL_BUDGET) - 0.05,
    );
    const device = Math.max(
      s.pixelSize > 0 ? Math.round(s.pixelSize * dpr) : 1,
      budget,
      1,
    );
    const width = Math.max(1, Math.ceil((cssWidth * dpr) / device));
    const height = Math.max(1, Math.ceil((cssHeight * dpr) / device));
    const crt = s.crt > 0;
    const canvasWidth = crt ? width * device : width;
    const canvasHeight = crt ? height * device : height;
    if (canvas.width !== canvasWidth || canvas.height !== canvasHeight) {
      canvas.width = canvasWidth;
      canvas.height = canvasHeight;
    }
    canvas.style.width = `${(width * device) / dpr}px`;
    canvas.style.height = `${(height * device) / dpr}px`;
    canvas.style.imageRendering =
      !crt && s.pixelSize > 0 && device >= 2 ? 'pixelated' : 'auto';
    if (crt && (paintTarget.width !== width || paintTarget.height !== height)) {
      gl.bindTexture(gl.TEXTURE_2D, paintTarget.texture);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA8,
        width,
        height,
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        null,
      );
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.bindFramebuffer(gl.FRAMEBUFFER, paintTarget.framebuffer);
      gl.framebufferTexture2D(
        gl.FRAMEBUFFER,
        gl.COLOR_ATTACHMENT0,
        gl.TEXTURE_2D,
        paintTarget.texture,
        0,
      );
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      paintTarget.width = width;
      paintTarget.height = height;
    }
    view.cssWidth = cssWidth;
    view.cssHeight = cssHeight;
    view.block = device / dpr;
    view.device = device;
    view.width = width;
    view.height = height;
    view.crt = crt;
    if (!fieldProgram) return;
    const fieldWidth = clamp(Math.ceil(cssWidth / FIELD_SCALE), 8, 320);
    const fieldHeight = clamp(Math.ceil(cssHeight / FIELD_SCALE), 8, 320);
    if (fieldWidth === field.width && fieldHeight === field.height) return;
    dropField();
    field.width = fieldWidth;
    field.height = fieldHeight;
    fieldTargets = [
      makeTarget(fieldWidth, fieldHeight),
      makeTarget(fieldWidth, fieldHeight),
    ];
  };

  const stir = (
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    pushX: number,
    pushY: number,
    decay: number,
  ) => {
    const read = fieldTargets[0];
    const write = fieldTargets[1];
    if (!fieldProgram || !read || !write) return;
    gl.bindFramebuffer(gl.FRAMEBUFFER, write.framebuffer);
    gl.viewport(0, 0, field.width, field.height);
    gl.useProgram(fieldProgram.program);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, read.texture);
    const uniforms = fieldProgram.uniforms;
    gl.uniform1i(u(uniforms, 'uPrev'), 0);
    gl.uniform2f(u(uniforms, 'uSize'), field.width, field.height);
    gl.uniform2f(u(uniforms, 'uCss'), view.cssWidth, view.cssHeight);
    gl.uniform2f(u(uniforms, 'uFrom'), fromX, fromY);
    gl.uniform2f(u(uniforms, 'uTo'), toX, toY);
    gl.uniform2f(u(uniforms, 'uPush'), pushX, pushY);
    gl.uniform1f(u(uniforms, 'uRadius'), STIR_RADIUS);
    gl.uniform1f(u(uniforms, 'uDecay'), decay);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    fieldTargets = [write, read];
  };

  const frame = (now: number) => {
    raf = 0;
    if (lost) return;
    const s = getSettings();
    const dt = clamp((now - last) / 1000 || 0, 0, 0.05);
    last = Math.max(last, now);
    const pace = reduced ? 0.2 : 1;
    flow += dt * s.speed * 7 * pace;
    spin += dt * s.rotation * 0.2 * pace;
    if (opening < 1) opening = Math.min(1, opening + dt / 2.2);

    const tracking = s.mouse && pointer.inside;
    const steerTarget = tracking
      ? (pointer.x / view.cssWidth - 0.5) * 0.35 * s.strength
      : 0;
    steer.value += (steerTarget - steer.value) * (1 - Math.exp(-dt / 0.8));

    gl.bindVertexArray(vao);
    if (fieldProgram && fieldTargets.length) {
      const dx = pointer.x - pointer.lastX;
      const dy = pointer.y - pointer.lastY;
      const moved = tracking && pointer.ready && (dx !== 0 || dy !== 0);
      const decay = Math.exp(-dt / 1.6);
      if (moved || field.energy > 0.05) {
        const amount = 0.85 * s.strength * (reduced ? 0.4 : 1);
        const travel = moved ? Math.hypot(dx, dy) * amount : 0;
        const steps = Math.max(1, Math.ceil(travel / (STIR_RADIUS * 0.3)));
        for (let step = 0; step < steps; step++) {
          const a = step / steps;
          const b = (step + 1) / steps;
          stir(
            pointer.lastX + dx * a,
            pointer.lastY + dy * a,
            pointer.lastX + dx * b,
            pointer.lastY + dy * b,
            moved ? dx * (b - a) * amount : 0,
            moved ? dy * (b - a) * amount : 0,
            step === steps - 1 ? decay : 1,
          );
        }
        field.energy = field.energy * decay + travel;
        if (field.energy <= 0.05) {
          fieldTargets.forEach((target) => {
            gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer);
            gl.clearColor(0, 0, 0, 0);
            gl.clear(gl.COLOR_BUFFER_BIT);
          });
        }
      }
    }
    pointer.lastX = pointer.x;
    pointer.lastY = pointer.y;

    for (let index = twirls.length - 1; index >= 0; index--) {
      const twirl = twirls[index];
      if (!twirl) continue;
      twirl.age += dt;
      if (twirl.age >= 3.2) twirls.splice(index, 1);
    }
    twirlData.fill(0);
    twirls.forEach((twirl, index) => {
      const t = twirl.age;
      const rise = smoother(t / 0.25);
      const fall = 1 - smoother((t - 0.25) / 2.95);
      twirlData[index * 4] = twirl.x;
      twirlData[index * 4 + 1] = twirl.y;
      twirlData[index * 4 + 2] = twirl.direction * 1.9 * rise * fall;
      twirlData[index * 4 + 3] = 150 * (1 + 0.6 * smoother(t / 3.2));
    });

    const eased = 1 - Math.pow(1 - opening, 3);
    const unwind = 1 - eased;
    const fieldTexture = fieldTargets[0]?.texture ?? null;
    gl.bindFramebuffer(
      gl.FRAMEBUFFER,
      view.crt ? paintTarget.framebuffer : null,
    );
    gl.viewport(0, 0, view.width, view.height);
    gl.useProgram(paintProgram.program);
    const p = paintProgram.uniforms;
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, fieldTexture);
    gl.uniform1i(u(p, 'uField'), 0);
    gl.uniform1f(
      u(p, 'uFieldOn'),
      fieldTargets.length && field.energy > 0.05 ? 1 : 0,
    );
    gl.uniform2f(u(p, 'uCss'), view.cssWidth, view.cssHeight);
    gl.uniform2f(u(p, 'uCanvas'), view.width, view.height);
    gl.uniform1f(u(p, 'uBlock'), view.block);
    gl.uniform1f(u(p, 'uFlow'), flow);
    gl.uniform1f(
      u(p, 'uSpin'),
      -0.4 + spin + steer.value + 2.6 * unwind * unwind,
    );
    gl.uniform2f(u(p, 'uOffset'), s.offset[0], s.offset[1]);
    gl.uniform3f(u(p, 'uColor1'), s.color1[0], s.color1[1], s.color1[2]);
    gl.uniform3f(u(p, 'uColor2'), s.color2[0], s.color2[1], s.color2[2]);
    gl.uniform3f(u(p, 'uColor3'), s.color3[0], s.color3[1], s.color3[2]);
    gl.uniform1f(u(p, 'uContrast'), s.contrast);
    gl.uniform1f(u(p, 'uLighting'), s.lighting);
    gl.uniform1f(u(p, 'uSwirl'), Math.min(1, s.swirl + 0.55 * unwind));
    gl.uniform1f(u(p, 'uScale'), s.scale);
    gl.uniform1i(u(p, 'uDetail'), s.detail);
    gl.uniform4fv(u(p, 'uTwirls'), twirlData);
    gl.uniform1f(u(p, 'uReveal'), smoother(opening / 0.45));
    gl.uniform1f(u(p, 'uLight'), s.light ? 1 : 0);
    gl.uniform1f(u(p, 'uOpacity'), s.opacity);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    if (view.crt) {
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.useProgram(screenProgram.program);
      const v = screenProgram.uniforms;
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, paintTarget.texture);
      gl.uniform1i(u(v, 'uPaint'), 0);
      gl.uniform2f(u(v, 'uCanvas'), canvas.width, canvas.height);
      gl.uniform2f(u(v, 'uSource'), view.width, view.height);
      gl.uniform1f(u(v, 'uDevice'), view.device);
      gl.uniform1f(u(v, 'uCrt'), s.crt);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    }

    const settling =
      Math.abs(steerTarget - steer.value) > 0.0005 ||
      field.energy > 0.05 ||
      twirls.length > 0;
    const busy = s.speed > 0 || s.rotation !== 0 || opening < 1 || settling;
    if (busy && visible && pageVisible) raf = requestAnimationFrame(frame);
  };

  const wake = () => {
    if (raf || lost || !visible || !pageVisible) return;
    last = performance.now();
    raf = requestAnimationFrame(frame);
  };

  const locate = (event: BalatroPointer) => {
    const rect = container.getBoundingClientRect();
    return {
      x: event.clientX - rect.left,
      y: event.clientY - rect.top,
      inside:
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom,
    };
  };

  const leave = () => {
    pointer.inside = false;
    wake();
  };

  const onLost = (event: Event) => {
    event.preventDefault();
    lost = true;
    cancelAnimationFrame(raf);
    raf = 0;
  };
  canvas.addEventListener('webglcontextlost', onLost);
  canvas.addEventListener('webglcontextrestored', onRestored);

  resize();
  wake();

  return {
    resize,
    wake,
    pointerMove(event) {
      const spot = locate(event);
      if (!pointer.ready || !pointer.inside) {
        pointer.lastX = spot.x;
        pointer.lastY = spot.y;
      }
      pointer.vx = spot.x - pointer.x;
      pointer.x = spot.x;
      pointer.y = spot.y;
      pointer.inside = spot.inside;
      pointer.ready = true;
      wake();
    },
    pointerDown(event) {
      const s = getSettings();
      const spot = locate(event);
      if (!spot.inside || !s.clickSwirl || reduced) return;
      twirls.push({
        x: spot.x,
        y: spot.y,
        age: 0,
        direction: pointer.vx < 0 ? 1 : -1,
      });
      if (twirls.length > MAX_TWIRLS) twirls.shift();
      wake();
    },
    pointerUp(event) {
      if (event.pointerType !== 'mouse') leave();
    },
    leave,
    setVisible(value) {
      visible = value;
      wake();
    },
    setPageVisible(value) {
      pageVisible = value;
      wake();
    },
    loseContext() {
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
    destroy() {
      cancelAnimationFrame(raf);
      raf = 0;
      canvas.removeEventListener('webglcontextlost', onLost);
      canvas.removeEventListener('webglcontextrestored', onRestored);
      if (!gl.isContextLost()) {
        dropField();
        gl.deleteTexture(paintTarget.texture);
        gl.deleteFramebuffer(paintTarget.framebuffer);
        gl.deleteVertexArray(vao);
        gl.deleteProgram(paintProgram.program);
        gl.deleteProgram(screenProgram.program);
        if (fieldProgram) gl.deleteProgram(fieldProgram.program);
      }
    },
  };
}

export const PIXEL_BUDGET = 2.4e6;
export const MAX_TWIRLS = 4;
export const FIELD_SCALE = 8;
export const STIR_RADIUS = 90;

export const VERTEX = /* glsl */ `#version 300 es
const vec2 corners[3] = vec2[3](vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0));
void main() {
  gl_Position = vec4(corners[gl_VertexID], 0.0, 1.0);
}`;

export const FIELD = /* glsl */ `#version 300 es
precision highp float;
uniform sampler2D uPrev;
uniform vec2 uSize;
uniform vec2 uCss;
uniform vec2 uFrom;
uniform vec2 uTo;
uniform vec2 uPush;
uniform float uRadius;
uniform float uDecay;
out vec4 fragColor;

void main() {
  vec2 cell = gl_FragCoord.xy / uSize;
  vec2 p = vec2(cell.x, 1.0 - cell.y) * uCss;
  vec2 seg = uTo - uFrom;
  float len2 = max(dot(seg, seg), 1e-6);
  float h = clamp(dot(p - uFrom, seg) / len2, 0.0, 1.0);
  vec2 gap = p - uFrom - seg * h;
  vec2 delta = uPush * exp(-dot(gap, gap) / (uRadius * uRadius));
  vec2 src = p - delta;
  vec2 prev = texture(uPrev, vec2(src.x / uCss.x, 1.0 - src.y / uCss.y)).xy;
  fragColor = vec4((prev + delta) * uDecay, 0.0, 1.0);
}`;

export const PAINT = /* glsl */ `#version 300 es
precision highp float;
uniform vec2 uCss;
uniform vec2 uCanvas;
uniform float uBlock;
uniform float uFlow;
uniform float uSpin;
uniform vec2 uOffset;
uniform vec3 uColor1;
uniform vec3 uColor2;
uniform vec3 uColor3;
uniform float uContrast;
uniform float uLighting;
uniform float uSwirl;
uniform float uScale;
uniform int uDetail;
uniform sampler2D uField;
uniform float uFieldOn;
uniform vec4 uTwirls[${MAX_TWIRLS}];
uniform float uReveal;
uniform float uLight;
uniform float uOpacity;
out vec4 fragColor;

vec3 paint(vec2 screenSize, vec2 coords) {
  vec2 uv = (coords - 0.5 * screenSize) / length(screenSize) - uOffset;
  float radius = length(uv);
  float speed = uSpin + 302.2;
  float angle = atan(uv.y, uv.x) + speed - 20.0 * (uSwirl * radius + (1.0 - uSwirl));
  vec2 mid = (screenSize / length(screenSize)) / 2.0;
  uv = vec2(radius * cos(angle) + mid.x, radius * sin(angle) + mid.y) - mid;

  uv *= 30.0 / uScale;
  speed = uFlow;
  vec2 uv2 = vec2(uv.x + uv.y);
  for (int i = 0; i < 8; i++) {
    if (i >= uDetail) break;
    uv2 += sin(max(uv.x, uv.y)) + uv;
    uv += 0.5 * vec2(cos(5.1123314 + 0.353 * uv2.y + speed * 0.131121), sin(uv2.x - 0.113 * speed));
    uv -= cos(uv.x + uv.y) - sin(uv.x * 0.711 - uv.y);
  }

  float contrastMod = 0.25 * uContrast + 0.5 * uSwirl + 1.2;
  float amount = min(2.0, max(0.0, length(uv) * 0.035 * contrastMod));
  float c1 = max(0.0, 1.0 - contrastMod * abs(1.0 - amount));
  float c2 = max(0.0, 1.0 - contrastMod * abs(amount));
  float c3 = 1.0 - min(1.0, c1 + c2);
  float light = (uLighting - 0.2) * max(c1 * 5.0 - 4.0, 0.0) + uLighting * max(c2 * 5.0 - 4.0, 0.0);
  vec3 gap = uLight > 0.5 ? mix(uColor3, vec3(1.0), 0.9) : uColor3;
  float base = 0.3 / uContrast;
  vec3 color = base * uColor1 + (1.0 - base) * (uColor1 * c1 + uColor2 * c2 + gap * c3) + light;
  return mix(gap, color, uReveal);
}

void main() {
  vec2 cell = floor(gl_FragCoord.xy) + 0.5;
  vec2 p = vec2(cell.x, uCanvas.y - cell.y) * uBlock;
  if (uFieldOn > 0.5) {
    p -= texture(uField, vec2(p.x / uCss.x, 1.0 - p.y / uCss.y)).xy;
  }
  for (int i = 0; i < ${MAX_TWIRLS}; i++) {
    vec4 twirl = uTwirls[i];
    if (twirl.w <= 0.0) continue;
    vec2 rel = p - twirl.xy;
    float turn = twirl.z * exp(-dot(rel, rel) / (twirl.w * twirl.w));
    float c = cos(turn);
    float s = sin(turn);
    p = twirl.xy + vec2(c * rel.x - s * rel.y, s * rel.x + c * rel.y);
  }
  vec3 color = paint(uCss, vec2(p.x, uCss.y - p.y));
  float grain = (fract(52.9829189 * fract(dot(cell, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;
  color = clamp(color + grain, 0.0, 1.0);
  fragColor = vec4(color * uOpacity, uOpacity);
}`;

export const SCREEN = /* glsl */ `#version 300 es
precision highp float;
uniform sampler2D uPaint;
uniform vec2 uCanvas;
uniform vec2 uSource;
uniform float uDevice;
uniform float uCrt;
out vec4 fragColor;

float smoother(float edge0, float edge1, float x) {
  float t = clamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

void main() {
  vec2 device = vec2(gl_FragCoord.x, uCanvas.y - gl_FragCoord.y);
  vec2 cell = floor(device / uDevice);
  vec4 texel = texture(uPaint, vec2((cell.x + 0.5) / uSource.x, 1.0 - (cell.y + 0.5) / uSource.y));
  vec3 color = texel.rgb;
  float glow = dot(color, vec3(0.2126, 0.7152, 0.0722));
  float period = max(uDevice, 3.0);
  float row = fract(device.y / period);
  float line = smoother(0.5, 0.92, row) * (1.0 - smoother(0.92, 1.0, row));
  color *= 1.0 - uCrt * 0.34 * line * (1.0 - 0.7 * glow);
  vec2 screen = gl_FragCoord.xy / uCanvas;
  float edge = smoother(0.0, 0.18, screen.x) * smoother(0.0, 0.18, 1.0 - screen.x);
  edge *= smoother(0.0, 0.24, screen.y) * smoother(0.0, 0.24, 1.0 - screen.y);
  color *= mix(1.0, 0.78 + 0.22 * edge, uCrt);
  color *= 1.0 + uCrt * 0.1;
  fragColor = vec4(min(color, vec3(texel.a)), texel.a);
}`;

export interface BalatroProps {
  /** Main paint color. */
  color1?: string;
  /** Second paint color, swirled into the first. */
  color2?: string;
  /** Color of the gaps between the two paints. */
  color3?: string;
  /** How sharply the paints separate. Lower values blend them into soft washes. */
  contrast?: number;
  /** Strength of the glossy highlights on the paint. */
  lighting?: number;
  /** How tightly the paint spirals around the center, from 0 to 1. */
  swirl?: number;
  /** How fast the paint flows. 0 freezes it. */
  speed?: number;
  /** Turns the whole swirl continuously. Negative values turn it the other way. */
  rotationSpeed?: number;
  /** Size of the paint shapes. Higher values zoom in. */
  scale?: number;
  /** How many times the paint folds over itself, from 1 to 8. */
  detail?: number;
  /** Moves the center of the swirl, as a fraction of the container diagonal. */
  offset?: [number, number];
  /** Size of the pixels in CSS pixels. 0 renders it smooth. */
  pixelSize?: number;
  /** Scanlines and soft edge falloff of an old CRT screen, from 0 to 1. */
  crt?: number;
  /** The cursor stirs the paint and steers the swirl. */
  mouseInteraction?: boolean;
  /** How strongly the cursor drags the paint along. */
  mouseStrength?: number;
  /** Clicking spins the paint into a whirlpool that slowly unwinds. */
  clickSwirl?: boolean;
  /** The swirl spins into place on mount. */
  intro?: boolean;
  /** Lightens the gaps between the paints so it sits on light pages. */
  lightMode?: boolean;
  /** Overall opacity, from 0 to 1. */
  opacity?: number;
  /** Highest pixel ratio the canvas renders at. */
  maxDevicePixelRatio?: number;
  class?: string;
}

export type BalatroRgb = [number, number, number];

export interface BalatroSettings {
  color1: BalatroRgb;
  color2: BalatroRgb;
  color3: BalatroRgb;
  contrast: number;
  lighting: number;
  swirl: number;
  speed: number;
  rotation: number;
  scale: number;
  detail: number;
  offset: [number, number];
  pixelSize: number;
  crt: number;
  mouse: boolean;
  strength: number;
  clickSwirl: boolean;
  intro: boolean;
  light: boolean;
  opacity: number;
  maxRatio: number;
}

export interface BalatroUniforms {
  [name: string]: WebGLUniformLocation | undefined;
}

export interface BalatroProgram {
  program: WebGLProgram;
  uniforms: BalatroUniforms;
}

export interface BalatroTarget {
  texture: WebGLTexture | null;
  framebuffer: WebGLFramebuffer | null;
}

export interface BalatroTwirl {
